     1→import { NextResponse } from 'next/server';
     2→import { AIRTABLE_CONFIG } from '../../../../lib/airtable-config.js';
     3→export const dynamic = 'force-dynamic';
     4→
     5→// ---- CONFIG ----
     6→const atBase  = () => process.env.AIRTABLE_BASE_ID;
     7→const atKey   = () => process.env.AIRTABLE_API_KEY;
     8→const tblQ    = () => AIRTABLE_CONFIG.QUOTES_TABLE;
     9→const tblLI   = () => AIRTABLE_CONFIG.LINE_ITEMS_TABLE;
    10→const tokCol  = () => AIRTABLE_CONFIG.TOKEN_FIELD;
    11→const liQuoteIdLookup = () => AIRTABLE_CONFIG.QUOTE_ID_LOOKUP_FIELD;
    12→
    13→// ---- Airtable helper ----
    14→async function ats(url, init) {
    15→  const res = await fetch(url, {
    16→    ...init,
    17→    headers: {
    18→      Authorization: `Bearer ${atKey()}`,
    19→      'Content-Type': 'application/json',
    20→      ...(init?.headers || {})
    21→    },
    22→    cache: 'no-store'
    23→  });
    24→  const body = await res.text();
    25→  if (!res.ok) {
    26→    const err = new Error(`Airtable ${res.status}: ${body}`);
    27→    err.status = res.status;
    28→    throw err;
    29→  }
    30→  return body ? JSON.parse(body) : {};
    31→}
    32→
    33→// ---- GET ----
    34→export async function GET(_req, { params }) {
    35→  try {
    36→    const base = atBase(), quotes = tblQ(), lines = tblLI();
    37→    const token = params.token;
    38→
    39→    const ff = `{${tokCol()}}='${token}'`;
    40→    const qUrl = `https://api.airtable.com/v0/${base}/${encodeURIComponent(quotes)}?filterByFormula=${encodeURIComponent(ff)}&maxRecords=1`;
    41→    const qRes = await ats(qUrl);
    42→    const quote = qRes.records?.[0] || null;
    43→    if (!quote) return NextResponse.json({ error: 'not found' }, { status: 404 });
    44→
    45→    const quoteId = quote.fields?.[AIRTABLE_CONFIG.FIELDS.QUOTE_ID] || '';
    46→    const liFilter = `{${liQuoteIdLookup()}}='${quoteId}'`;
    47→    const liUrl = `https://api.airtable.com/v0/${base}/${encodeURIComponent(lines)}?filterByFormula=${encodeURIComponent(liFilter)}&pageSize=100`;
    48→    const liRes = await ats(liUrl);
    49→    const lineItems = liRes.records || [];
    50→
    51→    // Calculate totals from the quote fields - prefer annual totals
    52→    const totals = {
