import { NextResponse } from 'next/server';
import { AIRTABLE_CONFIG } from '../../../../lib/airtable-config.js';
export const dynamic = 'force-dynamic';

// ---- CONFIG ----
const atBase  = () => process.env.AIRTABLE_BASE_ID;
const atKey   = () => process.env.AIRTABLE_API_KEY;
const tblQ    = () => AIRTABLE_CONFIG.QUOTES_TABLE;
const tblLI   = () => AIRTABLE_CONFIG.LINE_ITEMS_TABLE;
const tokCol  = () => AIRTABLE_CONFIG.TOKEN_FIELD;
const liQuoteIdLookup = () => AIRTABLE_CONFIG.QUOTE_ID_LOOKUP_FIELD;

// ---- Airtable helper ----
async function ats(url, init) {
  const res = await fetch(url, {
    ...init,
    headers: {
      Authorization: `Bearer ${atKey()}`,
      'Content-Type': 'application/json',
      ...(init?.headers || {})
    },
    cache: 'no-store'
  });
  const body = await res.text();
  if (!res.ok) {
    const err = new Error(`Airtable ${res.status}: ${body}`);
    err.status = res.status;
    throw err;
  }
  return body ? JSON.parse(body) : {};
}

// ---- GET ----
export async function GET(_req, { params }) {
  try {
    const base = atBase(), quotes = tblQ(), lines = tblLI();
    const token = params.token;

    const ff = `{${tokCol()}}='${token}'`;
    const qUrl = `https://api.airtable.com/v0/${base}/${encodeURIComponent(quotes)}?filterByFormula=${encodeURIComponent(ff)}&maxRecords=1`;
    const qRes = await ats(qUrl);
    const quote = qRes.records?.[0] || null;
    if (!quote) return NextResponse.json({ error: 'not found' }, { status: 404 });

    const quoteId = quote.fields?.[AIRTABLE_CONFIG.FIELDS.QUOTE_ID] || '';
    const liFilter = `{${liQuoteIdLookup()}}='${quoteId}'`;
    const liUrl = `https://api.airtable.com/v0/${base}/${encodeURIComponent(lines)}?filterByFormula=${encodeURIComponent(liFilter)}&pageSize=100`;
    const liRes = await ats(liUrl);
    const lineItems = liRes.records || [];

    // Calculate totals from the quote fields - prefer annual totals
    const totals = {
      alacarteTotal: quote.fields?.['A La Carte Total Annual'] || quote.fields?.['A La Carte Total'] || 0,
      memberTotal: quote.fields?.['Handld Total Annual'] || quote.fields?.['Handld Total'] || 0,
      savings: (quote.fields?.['A La Carte Total Annual'] || quote.fields?.['A La Carte Total'] || 0) - 
               (quote.fields?.['Handld Total Annual'] || quote.fields?.['Handld Total'] || 0)
    };

    return NextResponse.json({ 
      quote, 
      lineItems,
      totals,
      quoteRequest: quote.fields // For backward compatibility
    });
  } catch (e) {
    const status = e?.status ? Number(e.status) : 500;
    return NextResponse.json({ error: e?.message || 'unknown' }, { status });
  }
}

// ---- PUT: save frequency + sync Selected Services ----
export async function PUT(req, { params }) {
  try {
    const base = atBase(), quotes = tblQ(), lines = tblLI();
    const token = params.token;
    const body = await req.json().catch(() => ({}));

    const lineItems = Array.isArray(body?.lineItems) ? body.lineItems : [];
    const headerFields = body?.quote?.fields || null;

    const out = {};

    if (lineItems.length) {
      // For single-select, send string option name ("5"), or null to clear
      const sanitized = lineItems.map((r) => {
        let v = r?.fields?.[AIRTABLE_CONFIG.FIELDS.CHOSEN_FREQUENCY];
        if (v === '' || typeof v === 'undefined') v = null;
        if (v !== null) v = String(v); // ensure string option
        return {
          id: r.id,
          fields: {
            ...(typeof r?.fields?.[AIRTABLE_CONFIG.FIELDS.CHOSEN_FREQUENCY] !== 'undefined' && {
              [AIRTABLE_CONFIG.FIELDS.CHOSEN_FREQUENCY]: v
            })
            // NOTE: we no longer send "Notes" to avoid 422 UNKNOWN_FIELD_NAME
          }
        };
      });

      const liUrl = `https://api.airtable.com/v0/${base}/${encodeURIComponent(lines)}`;
      const liRes = await ats(liUrl, { method: 'PATCH', body: JSON.stringify({ records: sanitized }) });
      out.lineItems = liRes.records || [];
    }

    // find quote by token (for header updates)
    const ff = `{${tokCol()}}='${token}'`;
    const lookup = await ats(
      `https://api.airtable.com/v0/${base}/${encodeURIComponent(quotes)}?filterByFormula=${encodeURIComponent(ff)}&maxRecords=1`
    );
    const quote = lookup.records?.[0] || null;
    if (!quote) throw new Error('Quote not found while updating');

    // sync Selected Services if not explicitly provided
    let selected = Array.isArray(body?.selectedServices) ? body.selectedServices : null;
    if (!selected && lineItems.length) {
      selected = lineItems
        .filter((r) => {
          const v = r?.fields?.[AIRTABLE_CONFIG.FIELDS.CHOSEN_FREQUENCY];
          const n = v ? parseInt(v, 10) : 0;
          return Number.isFinite(n) && n > 0;
        })
        .map((r) => String(r?.fields?.[AIRTABLE_CONFIG.FIELDS.SERVICE] || ''))
        .filter(Boolean);
    }

    const finalHeader = { ...(headerFields || {}) };
    if (selected) finalHeader[AIRTABLE_CONFIG.FIELDS.SELECTED_SERVICES] = selected;

    if (Object.keys(finalHeader).length) {
      const qRes = await ats(
        `https://api.airtable.com/v0/${base}/${encodeURIComponent(quotes)}`,
        { method: 'PATCH', body: JSON.stringify({ records: [{ id: quote.id, fields: finalHeader }] }) }
      );
      out.quote = qRes.records?.[0] || null;
    }

    return NextResponse.json({ ok: true, ...out });
  } catch (e) {
    return NextResponse.json({ error: e?.message || 'update failed' }, { status: 500 });
  }
}

