// lib/airtable.js
import 'server-only';
import { AIRTABLE_CONFIG } from './airtable-config.js';

const API = 'https://api.airtable.com/v0';

// Airtable credentials (sensitive)
const KEY = process.env.AIRTABLE_API_KEY;
const BASE = process.env.AIRTABLE_BASE_ID;

// Table and field names (from constants)
const QUOTES_TBL = AIRTABLE_CONFIG.QUOTES_TABLE;
const LINES_TBL = AIRTABLE_CONFIG.LINE_ITEMS_TABLE;
const LINK_FIELD = AIRTABLE_CONFIG.LINK_FIELD;
const TOKEN_FIELD = AIRTABLE_CONFIG.TOKEN_FIELD;

// Optional configuration
const VIEW = process.env.AIRTABLE_ALLOWED_VIEW || '';

if (!KEY || !BASE) {
  throw new Error('Missing required Airtable credentials: AIRTABLE_API_KEY and AIRTABLE_BASE_ID');
}

async function ats(path, init) {
  const res = await fetch(`${API}/${BASE}/${encodeURIComponent(path)}`, {
    ...init,
    headers: {
      Authorization: `Bearer ${KEY}`,
      'Content-Type': 'application/json',
      ...(init && init.headers ? init.headers : {}),
    },
    cache: 'no-store',
  });
  if (!res.ok) {
    const txt = await res.text();
    const err = new Error(`Airtable ${res.status}: ${txt}`);
    err.status = res.status;
    throw err;
  }
  return res.json();
}

// === v5 === ALWAYS find the quote by the Token field (no direct GET) ===
export async function getQuoteByToken(token) {
  // 1) find the quote row by Token field
  const ff = `{${TOKEN_FIELD}}='${token}'`;
  const q = await ats(
    `${encodeURIComponent(QUOTES_TBL)}?filterByFormula=${encodeURIComponent(ff)}&maxRecords=1`
  );
  const quote = (q.records && q.records[0]) || null;
  if (!quote) {
    const nf = new Error('not found');
    nf.status = 404;
    throw nf;
  }

  // 2) fetch line items linked to this quote
  const filter = encodeURIComponent(`FIND("${quote.id}", ARRAYJOIN({${LINK_FIELD}}))`);
  const viewParam = VIEW ? `&view=${encodeURIComponent(VIEW)}` : '';
  const liResp = await ats(
    `${encodeURIComponent(LINES_TBL)}?filterByFormula=${filter}${viewParam}`
  );

  return { quote, lineItems: liResp.records || [] };
}

export async function updateLineItems(recordUpdates) {
  if (!Array.isArray(recordUpdates) || !recordUpdates.length) return [];
  const resp = await ats(`${encodeURIComponent(LINES_TBL)}`, {
    method: 'PATCH',
    body: JSON.stringify({ records: recordUpdates }),
  });
  return resp.records || [];
}

export async function updateQuote(recordId, fields) {
  if (!recordId || !fields || !Object.keys(fields).length) return null;
  const resp = await ats(`${encodeURIComponent(QUOTES_TBL)}`, {
    method: 'PATCH',
    body: JSON.stringify({ records: [{ id: recordId, fields }] }),
  });
  return (resp.records && resp.records[0]) || null;
}

