```

## Field Mapping Strategy

Create mapper functions that transform Airtable's field names to clean property names:

```typescript
// lib/mappers/quote.mapper.ts
export function mapAirtableToQuote(record: AirtableRecord): Quote {
  return {
    id: record.id,
    quoteId: record.fields['Quote ID'],
    token: record.fields['Token'],
    firstName: record.fields['First Name'],
    lastName: record.fields['Last Name'],
    email: record.fields['Email'],
    city: record.fields['City'],
    stories: record.fields['Stories'],
    squareFootage: record.fields['Square Footage'],
    lotSize: record.fields['Lot Size'],
    alaCarteTotal: record.fields['A La Carte Total Annual'] || record.fields['A La Carte Total'],
    handldTotal: record.fields['Handld Total Annual'] || record.fields['Handld Total'],
    selectedServices: record.fields['Selected Services'] || []
  };
}

// Reverse mapper for updates
export function mapQuoteToAirtable(quote: Partial<Quote>): AirtableFields {
  const fields: AirtableFields = {};

  if (quote.firstName !== undefined) fields['First Name'] = quote.firstName;
  if (quote.lastName !== undefined) fields['Last Name'] = quote.lastName;
