import type { Quote } from '@/types/models';
import type { AirtableQuoteRecord, AirtableQuoteFields } from '@/types/airtable';

/**
 * Maps an Airtable quote record to our domain Quote model
 */
export function mapAirtableToQuote(record: AirtableQuoteRecord): Quote {
  const fields = record.fields;

  return {
    id: record.id,
    quoteId: fields['Quote ID'] || '',
    token: fields['Token'] || '',
    firstName: fields['First Name'] || '',
    lastName: fields['Last Name'] || '',
    email: fields['Email'] || '',
    city: fields['City'] || '',
    stories: fields['Stories'],
    squareFootage: fields['Square Footage'],
    lotSize: fields['Lot Size'],
    alaCarteTotal: fields['A La Carte Total'] || 0,
    handldTotal: fields['Handld Total'] || 0,
    alaCarteTotalAnnual: fields['A La Carte Total Annual'],
    handldTotalAnnual: fields['Handld Total Annual'],
    selectedServices: fields['Selected Services'] || [],
    createdAt: fields['Created At'] || record.createdTime,
    updatedAt: fields['Updated At']
  };
}

/**
 * Maps our domain Quote model back to Airtable fields for updates
 * Only includes fields that are defined (partial update)
 */
export function mapQuoteToAirtable(quote: Partial<Quote>): Partial<AirtableQuoteFields> {
  const fields: Partial<AirtableQuoteFields> = {};

  if (quote.quoteId !== undefined) fields['Quote ID'] = quote.quoteId;
  if (quote.token !== undefined) fields['Token'] = quote.token;
  if (quote.firstName !== undefined) fields['First Name'] = quote.firstName;
  if (quote.lastName !== undefined) fields['Last Name'] = quote.lastName;
  if (quote.email !== undefined) fields['Email'] = quote.email;
  if (quote.city !== undefined) fields['City'] = quote.city;
  if (quote.stories !== undefined) fields['Stories'] = quote.stories;
  if (quote.squareFootage !== undefined) fields['Square Footage'] = quote.squareFootage;
  if (quote.lotSize !== undefined) fields['Lot Size'] = quote.lotSize;
  if (quote.alaCarteTotal !== undefined) fields['A La Carte Total'] = quote.alaCarteTotal;
  if (quote.handldTotal !== undefined) fields['Handld Total'] = quote.handldTotal;
  if (quote.alaCarteTotalAnnual !== undefined) fields['A La Carte Total Annual'] = quote.alaCarteTotalAnnual;
  if (quote.handldTotalAnnual !== undefined) fields['Handld Total Annual'] = quote.handldTotalAnnual;
  if (quote.selectedServices !== undefined) fields['Selected Services'] = quote.selectedServices;

  return fields;
}

/**
 * Calculates quote totals from the quote fields
 */
export function calculateQuoteTotals(quote: Quote) {
  // Prefer annual totals if available
  const alacarteTotal = quote.alaCarteTotalAnnual || quote.alaCarteTotal || 0;
  const memberTotal = quote.handldTotalAnnual || quote.handldTotal || 0;

  return {
    alacarteTotal,
    memberTotal,
    savings: alacarteTotal - memberTotal
  };
}

