// app/q/[token]/page.tsx
'use client';

import { useEffect, useMemo, useState } from 'react';
import { useParams, useSearchParams } from 'next/navigation';
import LineItemsTable from '../../components/LineItemsTable';
import type { Quote, LineItem, QuoteTotals } from '@/types/models';

const fmtMoney = (n: number | undefined): string =>
  typeof n === 'number' && !Number.isNaN(n)
    ? n.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })
    : '-';

interface QuoteData {
  quote: Quote;
  lineItems: LineItem[];
  totals: QuoteTotals;
}

/**
 * Resilient READ fetch:
 * - Try NEXT_PUBLIC_API_BASE (if present) and the viewer origin
 * - For each base, try common endpoint shapes
 * - Return the first JSON that succeeds
 */
async function fetchQuoteResilient(token: string): Promise<{ data: QuoteData; okUrl: string }> {
  const origin = typeof window !== 'undefined' ? window.location.origin : '';
  const envBase = (process.env.NEXT_PUBLIC_API_BASE || '').replace(/\/$/, '');
  const bases = [envBase, origin].filter(Boolean);

  const tried: string[] = [];
  for (const base of bases) {
    const urls = [
      `${base}/api/quote/${token}`,
      `${base}/api/quotes/${token}`,
      `${base}/api/quote?token=${encodeURIComponent(token)}`,
    ];
    for (const url of urls) {
      tried.push(url);
      try {
        const res = await fetch(url, { cache: 'no-store' });
        if (!res.ok) continue;
        const data = await res.json();
        // Basic sanity check - a quote payload usually has these fields
        if (data && (Array.isArray(data.lineItems) || data.quote)) {
          return { data, okUrl: url };
        }
      } catch {
        // move on to the next candidate
      }
    }
  }

  // If everything failed, show the URLs we tried to make troubleshooting easy
  throw new Error(`Failed to fetch quote. Tried:\n- ${tried.join('\n- ')}`);
}

function fmtPossessive(name: string | undefined): string {
  if (!name) return 'Your';
  return /s$/i.test(name) ? `${name}'` : `${name}'s`;
}

export default function QuoteViewerPage() {
  const params = useParams();
  const search = useSearchParams();
  const token = params?.token as string;
  const debug = search?.get('debug') === '1';

  const [loading, setLoading] = useState(true);
  const [quoteData, setQuoteData] = useState<QuoteData | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let mounted = true;
    (async () => {
      setLoading(true);
      setError(null);
      try {
        if (!token) throw new Error('Missing token in URL.');
        const { data } = await fetchQuoteResilient(token);
        if (!mounted) return;
        setQuoteData(data);
      } catch (e: any) {
        if (mounted) setError(e?.message || 'Failed to load quote');
      } finally {
        if (mounted) setLoading(false);
      }
    })();
    return () => {
      mounted = false;
    };
  }, [token]);

  const handleFrequencyChange = async (itemId: string, frequency: number) => {
    if (!quoteData) return;

    try {
      const response = await fetch(`/api/quotes/${token}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          lineItems: [{ id: itemId, chosenFrequency: frequency }]
        })
      });

      if (response.ok) {
        // Refresh the quote data
        const { data } = await fetchQuoteResilient(token);
        setQuoteData(data);
      }
    } catch (error) {
      console.error('Failed to update frequency:', error);
      alert('Failed to update frequency. Please try again.');
    }
  };

  if (loading) {
    return <main className="p-6">Loading…</main>;
  }
  if (error) {
    return (
      <main className="p-6">
        <pre className="whitespace-pre-wrap rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">
          {error}
        </pre>
      </main>
    );
  }
  if (!quoteData) {
    return <main className="p-6">No quote found.</main>;
  }

  const { quote, lineItems, totals } = quoteData;
  const pageTitle = `${fmtPossessive(quote.firstName)} Handld Quote`;

  return (
    <main className="mx-auto max-w-4xl px-6 py-8 text-brand-navy">
      {/* Header with Logo */}
      <header className="mb-4">
        <div className="flex items-start gap-4 mb-4">
          {/* Logo */}
          <div className="flex-shrink-0">
            <img 
              src="/logo.png" 
              alt="Handld" 
              className="w-16 h-16 object-contain"
            />
          </div>

          {/* Quote Title */}
          <div className="flex-1">
            <h1 className="text-3xl font-bold mb-1 text-brand-navy">
              {pageTitle}
            </h1>
            {quote.quoteId && (
              <div className="text-sm text-brand-navy">
                Quote ID: {quote.quoteId}
              </div>
            )}
          </div>
        </div>
      </header>

      {/* Totals */}
      <section className="mb-4 grid grid-cols-1 gap-4 sm:grid-cols-3">
        <div className="border border-gray-200 rounded-xl p-4 text-center bg-brand-light-cream">
          <div className="text-xs font-medium uppercase tracking-wide mb-1 text-brand-navy">
            Standard Total
          </div>
          <div className="text-xl font-bold text-brand-navy">
            {fmtMoney(totals.alacarteTotal)}
          </div>
        </div>
        <div className="border border-gray-200 rounded-xl p-4 text-center bg-brand-light-cream">
          <div className="text-xs font-medium uppercase tracking-wide mb-1 text-brand-navy">
            Member Total
          </div>
          <div className="text-xl font-bold text-brand-navy">
            {fmtMoney(totals.memberTotal)}
          </div>
        </div>
        <div className="border border-gray-200 rounded-xl p-4 text-center bg-brand-light-cream">
          <div className="text-xs font-medium uppercase tracking-wide mb-1 text-brand-navy">
            Handld Member Savings
          </div>
          <div className="text-xl font-bold text-brand-navy">
            {fmtMoney(totals.savings)}
          </div>
        </div>
      </section>

      {/* Customer Information - Condensed */}
      <section className="mb-4">
        <div className="border border-gray-200 rounded-xl p-3 bg-brand-light-cream">
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {quote.firstName && quote.lastName && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600">Name</div>
                <div className="text-base font-medium text-brand-navy">
                  {quote.firstName} {quote.lastName}
                </div>
              </div>
            )}

            {quote.email && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600">Email</div>
                <div className="text-base text-brand-navy">
                  {quote.email}
                </div>
              </div>
            )}

            {quote.city && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600">City</div>
                <div className="text-base text-brand-navy">
                  {quote.city}
                </div>
              </div>
            )}

            {quote.stories && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600">Stories</div>
                <div className="text-base text-brand-navy">
                  {quote.stories}
                </div>
              </div>
            )}

            {quote.squareFootage && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600">Square Footage</div>
                <div className="text-base text-brand-navy">
                  {quote.squareFootage}
                </div>
              </div>
            )}

            {quote.lotSize && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600">Lot Size</div>
                <div className="text-base text-brand-navy">
                  {quote.lotSize}
                </div>
              </div>
            )}
          </div>
        </div>
      </section>

      {/* Services */}
      <section className="mb-4">
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-2xl font-bold text-brand-navy">Services</h2>
          <button
            onClick={() => {
              alert('TODO: Add new service to quote');
            }}
            className="text-sm px-4 py-2 rounded-full border border-brand-navy text-brand-navy bg-brand-light-cream hover:bg-brand-cream"
          >
            + Add Service
          </button>
        </div>
        <LineItemsTable 
          lineItems={lineItems} 
          totals={totals} 
          onFrequencyChange={handleFrequencyChange}
        />
      </section>

      {/* Buttons */}
      <section className="flex flex-col sm:flex-row gap-4">
        <button
          className="flex-1 rounded-full py-4 px-8 text-lg font-semibold text-white bg-brand-navy"
        >
          Book Handld Membership — Save 30%
        </button>
        <button
          className="flex-1 rounded-full py-4 px-8 text-lg font-medium border-2 border-brand-navy text-brand-navy bg-brand-light-cream"
        >
          Book with Standard Pricing
        </button>
      </section>

      {debug && (
        <section className="mt-8 p-4 bg-gray-100 rounded-lg">
          <h3 className="font-bold mb-2">Debug Info</h3>
          <pre className="text-xs overflow-auto">
            {JSON.stringify({ quote, lineItems, totals }, null, 2)}
          </pre>
        </section>
      )}
    </main>
  );
}

