  if (!Array.isArray(recordUpdates) || recordUpdates.length === 0) {
    return [];
  }

  try {
    const updates = prepareLineItemUpdates(recordUpdates);
    const updatedRecords = await base(AIRTABLE_CONFIG.LINE_ITEMS_TABLE)
