  if (lineItem.description !== undefined) fields['Description'] = lineItem.description;
  if (lineItem.handldRate !== undefined) fields['Handld Rate'] = lineItem.handldRate;
  if (lineItem.alaCarteRate !== undefined) fields['A La Carte Rate'] = lineItem.alaCarteRate;

  // Convert number frequency back to string for Airtable single-select field
  if (lineItem.chosenFrequency !== undefined) {
    fields['Chosen Frequency'] = lineItem.chosenFrequency ? String(lineItem.chosenFrequency) : undefined;
  }

  if (lineItem.unit !== undefined) fields['Unit'] = lineItem.unit;

