import { mapAirtableToLineItems, prepareLineItemUpdates } from './mappers/lineItem.mapper';

// Validate environment variables
const API_KEY = process.env.AIRTABLE_API_KEY;
const BASE_ID = process.env.AIRTABLE_BASE_ID;

if (!API_KEY || !BASE_ID) {
  throw new Error('Missing required Airtable credentials: AIRTABLE_API_KEY and AIRTABLE_BASE_ID');
}

// Configure Airtable
const base = new Airtable({ apiKey: API_KEY }).base(BASE_ID);

// Optional view configuration
const ALLOWED_VIEW = process.env.AIRTABLE_ALLOWED_VIEW || '';

/**
 * Fetches a quote by its token, including all associated line items
 */
export async function getQuoteByToken(token: string): Promise<{ 
  quote: Quote; 
  lineItems: LineItem[]; 
  totals: QuoteTotals;
}> {
  try {
    // 1. Find the quote row by Token field
    const quoteRecords = await base(AIRTABLE_CONFIG.QUOTES_TABLE)
      .select({
        filterByFormula: `{${AIRTABLE_CONFIG.TOKEN_FIELD}}='${token}'`,
        maxRecords: 1
      })
      .firstPage();

    if (!quoteRecords || quoteRecords.length === 0) {
      const error = new Error('Quote not found');
      (error as any).status = 404;
      throw error;
    }

    const quoteRecord = quoteRecords[0] as unknown as AirtableQuoteRecord;
    const quote = mapAirtableToQuote(quoteRecord);

    // 2. Fetch line items linked to this quote using Quote ID
    const quoteId = quote.quoteId;
    const lineItemSelectOptions: any = {
      filterByFormula: `{${AIRTABLE_CONFIG.QUOTE_ID_LOOKUP_FIELD}}='${quoteId}'`
    };

    if (ALLOWED_VIEW) {
      lineItemSelectOptions.view = ALLOWED_VIEW;
    }

    const lineItemRecords = await base(AIRTABLE_CONFIG.LINE_ITEMS_TABLE)
      .select(lineItemSelectOptions)
      .all();
    const lineItems = mapAirtableToLineItems(lineItemRecords as unknown as AirtableLineItemRecord[]);

    // 3. Calculate totals
    const totals = calculateQuoteTotals(quote);

    return { quote, lineItems, totals };
  } catch (error) {
    console.error('Error fetching quote by token:', error);
    throw error;
  }
}

/**
 * Updates line items with new frequency selections
 */
export async function updateLineItems(
  recordUpdates: Array<{ id: string; chosenFrequency?: number }>
): Promise<LineItem[]> {
  if (!Array.isArray(recordUpdates) || recordUpdates.length === 0) {
    return [];
  }

  try {
    const updates = prepareLineItemUpdates(recordUpdates);
    const updatedRecords = await base(AIRTABLE_CONFIG.LINE_ITEMS_TABLE)
      .update(updates);

    return mapAirtableToLineItems(updatedRecords as unknown as AirtableLineItemRecord[]);
  } catch (error) {
    console.error('Error updating line items:', error);
    throw error;
  }
}

/**
 * Updates a quote record with new field values
 */
export async function updateQuote(
  recordId: string, 
  fields: Partial<Quote>
): Promise<Quote | null> {
  if (!recordId || !fields || Object.keys(fields).length === 0) {
    return null;
  }

  try {
    const airtableFields = mapQuoteToAirtable(fields);
    const updatedRecords = await base(AIRTABLE_CONFIG.QUOTES_TABLE)
      .update([{
        id: recordId,
        fields: airtableFields as Partial<FieldSet>
      }]);

    if (updatedRecords && updatedRecords.length > 0) {
      return mapAirtableToQuote(updatedRecords[0] as unknown as AirtableQuoteRecord);
    }

    return null;
  } catch (error) {
    console.error('Error updating quote:', error);
    throw error;
  }
}

/**
 * Finds a quote by token (used for updates)
 */
export async function findQuoteByToken(token: string): Promise<Quote | null> {
  try {
    const records = await base(AIRTABLE_CONFIG.QUOTES_TABLE)
      .select({
        filterByFormula: `{${AIRTABLE_CONFIG.TOKEN_FIELD}}='${token}'`,
        maxRecords: 1
      })
      .firstPage();

    if (records && records.length > 0) {
      return mapAirtableToQuote(records[0] as unknown as AirtableQuoteRecord);
    }

    return null;
  } catch (error) {
    console.error('Error finding quote by token:', error);
    throw error;
  }
}

