import { NextRequest, NextResponse } from 'next/server';
import { getQuoteByToken, updateLineItems, findQuoteByToken, updateQuote } from '@/lib/airtable';
import type { UpdateLineItemsRequest } from '@/types/models';

export const dynamic = 'force-dynamic';

// GET /api/quotes/[token]
export async function GET(
  _request: NextRequest,
  { params }: { params: { token: string } }
) {
  try {
    const { token } = params;

    if (!token) {
      return NextResponse.json(
        { error: 'Token is required' },
        { status: 400 }
      );
    }

    const result = await getQuoteByToken(token);

    // Include quoteRequest field for backward compatibility
    return NextResponse.json({
      ...result,
      quoteRequest: result.quote // Legacy field name
    });
  } catch (error: any) {
    const status = error?.status || 500;
    const message = error?.message || 'Failed to fetch quote';

    return NextResponse.json(
      { error: message },
      { status }
    );
  }
}

// PUT /api/quotes/[token]
export async function PUT(
  request: NextRequest,
  { params }: { params: { token: string } }
) {
  try {
    const { token } = params;
    const body: UpdateLineItemsRequest = await request.json();

    const response: any = { ok: true };

    // Update line items if provided
    if (body.lineItems && body.lineItems.length > 0) {
      const updatedLineItems = await updateLineItems(body.lineItems);
      response.lineItems = updatedLineItems;
    }

    // Find the quote to update selected services
    const quote = await findQuoteByToken(token);
    if (!quote) {
      return NextResponse.json(
        { error: 'Quote not found' },
        { status: 404 }
      );
    }

    // Build selected services from line items if not explicitly provided
    let selectedServices = body.selectedServices;
    if (!selectedServices && body.lineItems) {
      selectedServices = body.lineItems
        .filter(item => item.chosenFrequency && item.chosenFrequency > 0)
        .map(item => {
          // Find the service name from the line items
          // This would need to be passed in the request or fetched
          return ''; // Placeholder - needs service name
        })
        .filter(Boolean);
    }

    // Update quote if we have fields to update
    if (selectedServices) {
      const updatedQuote = await updateQuote(quote.id, { selectedServices });
      response.quote = updatedQuote;
    }

    return NextResponse.json(response);
  } catch (error: any) {
    const message = error?.message || 'Failed to update quote';

    return NextResponse.json(
      { error: message },
      { status: 500 }
    );
  }
}

'use client';

import type { LineItem, QuoteTotals } from '@/types/models';

const fmtMoney = (n: number | undefined): string =>
  typeof n === 'number' && !Number.isNaN(n)
    ? n.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })
    : '-';

interface LineItemsTableProps {
  lineItems: LineItem[];
  totals: QuoteTotals;
  onFrequencyChange?: (itemId: string, frequency: number) => void;
  onRemoveItem?: (itemId: string) => void;
}

export default function LineItemsTable({ 
  lineItems = [], 
  totals = { alacarteTotal: 0, memberTotal: 0, savings: 0 },
  onFrequencyChange,
  onRemoveItem
}: LineItemsTableProps) {
  if (!lineItems || lineItems.length === 0) {
    return null;
  }

  const handleFrequencyChange = (itemId: string, service: string, frequency: string) => {
    if (onFrequencyChange && frequency) {
      onFrequencyChange(itemId, parseInt(frequency, 10));
    } else {
      alert(`TODO: Update ${service} frequency to ${frequency}`);
    }
  };

  const handleRemoveItem = (itemId: string, service: string) => {
    if (onRemoveItem) {
      onRemoveItem(itemId);
    } else {
      alert(`TODO: Delete ${service} from quote`);
    }
  };

  return (
    <div className="border border-gray-200 rounded-xl bg-brand-light-cream overflow-hidden mb-4">
      {/* Header */}
      <div className="bg-brand-navy text-white p-4">
        <div className="grid gap-4 text-sm font-medium" style={{ gridTemplateColumns: '1fr 120px 120px 120px 80px' }}>
          <div className="text-left">Service</div>
          <div className="text-center">Frequency</div>
          <div className="text-right">Standard Price</div>
          <div className="text-right">Member Price</div>
          <div></div>
        </div>
      </div>

      {/* Data Rows */}
      {lineItems.map((item) => {
        const chosenFreq = item.chosenFrequency?.toString() || '';

        return (
          <div key={item.id} className="p-4 border-b border-gray-200 bg-brand-light-cream">
            <div className="grid gap-4 text-sm items-center" style={{ gridTemplateColumns: '1fr 120px 120px 120px 80px' }}>
              <div className="font-medium text-brand-navy">{item.service}</div>
              <div className="text-center">
                <select 
                  value={chosenFreq}
                  onChange={(e) => handleFrequencyChange(item.id, item.service, e.target.value)}
                  className="w-12 border border-gray-300 rounded-lg px-2 py-1 text-sm bg-white text-brand-navy text-center"
                >
                  <option value="">-</option>
                  {[...Array(12)].map((_, i) => (
                    <option key={i + 1} value={i + 1}>
                      {i + 1}
                    </option>
                  ))}
                </select>
              </div>
              <div className="text-right font-medium">{fmtMoney(item.alaCarteRate)}</div>
              <div className="text-right font-medium">{fmtMoney(item.handldRate)}</div>
              <div className="text-center">
                <button
                  onClick={() => handleRemoveItem(item.id, item.service)}
                  className="text-red-600 hover:text-red-800 text-sm px-2 py-1 rounded border border-red-300 hover:border-red-500"
                >
                  Remove
                </button>
              </div>
            </div>
          </div>
        );
      })}

      {/* Totals Row */}
      <div className="p-4 border-t-2 border-gray-400 bg-brand-light-cream">
        <div className="grid gap-4 text-sm font-bold items-center" style={{ gridTemplateColumns: '1fr 120px 120px 120px 80px' }}>
          <div></div>
          <div></div>
          <div className="text-right text-brand-navy">{fmtMoney(totals.alacarteTotal)}</div>
          <div className="text-right text-brand-navy">{fmtMoney(totals.memberTotal)}</div>
          <div></div>
        </div>
      </div>
    </div>
  );
}

