/**
 * Consolidated types for Airtable integration
 * Includes both domain models and Airtable-specific types
 */

import type { FieldSet } from 'airtable';

// ============================================
// Domain Models - Clean interfaces for the app
// ============================================

export interface Quote {
  id: string;
  quoteId: string;
  token: string;
  firstName: string;
  lastName: string;
  email: string;
  city: string;
  stories?: number;
  squareFootage?: number;
  lotSize?: number;
  alaCarteTotal: number;
  handldTotal: number;
  alaCarteTotalAnnual?: number;
  handldTotalAnnual?: number;
  selectedServices?: string[];
  createdAt?: string;
  updatedAt?: string;
}

export interface LineItem {
  id: string;
  service: string;
  description?: string;
  handldRate: number;
  alaCarteRate: number;
  chosenFrequency?: number;
  unit?: string;
  quoteId: string;
  linkToQuote?: string[];
}

export interface QuoteTotals {
  alacarteTotal: number;
  memberTotal: number;
  savings: number;
}

export interface QuoteWithLineItems {
  quote: Quote;
  lineItems: LineItem[];
  totals: QuoteTotals;
}

// ============================================
// API Types - Request/Response interfaces
// ============================================

export interface QuoteResponse {
  quote: Quote;
  lineItems: LineItem[];
  totals: QuoteTotals;
}

export interface UpdateLineItemsRequest {
  lineItems: Array<{
    id: string;
    chosenFrequency?: number;
  }>;
  selectedServices?: string[];
}

export interface UpdateLineItemsResponse {
  ok: boolean;
  lineItems?: LineItem[];
  quote?: Quote;
  error?: string;
}

// ============================================
// UI Component Props
// ============================================

export interface LineItemTableProps {
  lineItems: LineItem[];
  totals: QuoteTotals;
  onFrequencyChange?: (itemId: string, frequency: number) => void;
  onRemoveItem?: (itemId: string) => void;
}

// ============================================
// Airtable-Specific Types - Raw field mappings
// ============================================

export interface AirtableQuoteFields extends FieldSet {
  'Quote ID': string;
  'Token': string;
  'First Name': string;
  'Last Name': string;
  'Email': string;
  'City': string;
  'Stories'?: number;
  'Square Footage'?: number;
  'Lot Size'?: number;
  'A La Carte Total'?: number;
  'Handld Total'?: number;
  'A La Carte Total Annual'?: number;
  'Handld Total Annual'?: number;
  'Selected Services'?: string[];
  'Created At'?: string;
  'Updated At'?: string;
}

export interface AirtableLineItemFields extends FieldSet {
  'Service': string;
  'Description'?: string;
  'Handld Rate': number;
  'A La Carte Rate': number;
  'Chosen Frequency'?: string; // Single-select field in Airtable
  'Unit'?: string;
  'Quote ID (from Request)'?: string;
  'Link to Quote Request'?: string[];
}

// Airtable Record types
export interface AirtableQuoteRecord {
  id: string;
  fields: AirtableQuoteFields;
  createdTime?: string;
}

export interface AirtableLineItemRecord {
  id: string;
  fields: AirtableLineItemFields;
  createdTime?: string;
}

