/**
 * Maps an Airtable line item record to our domain LineItem model
 */
export function mapAirtableToLineItem(record: AirtableLineItemRecord): LineItem {
  const fields = record.fields;

  // Convert string frequency to number (e.g., "5" -> 5)
  const frequency = fields['Chosen Frequency'] ? parseInt(fields['Chosen Frequency'], 10) : undefined;

  // Handle pricing fields - can be arrays or single values, and have different field names
  let handldRate = 0;
  let alaCarteRate = 0;

  // Try "Handld Price" first, then "Handld Rate"
  if (fields['Handld Price'] !== undefined) {
    handldRate = Array.isArray(fields['Handld Price']) 
      ? fields['Handld Price'][0] || 0
      : fields['Handld Price'] || 0;
  } else if (fields['Handld Rate'] !== undefined) {
    handldRate = fields['Handld Rate'] || 0;
  }

  // Try "A La Carte Price" first, then "A La Carte Rate"
  if (fields['A La Carte Price'] !== undefined) {
    alaCarteRate = Array.isArray(fields['A La Carte Price'])
      ? fields['A La Carte Price'][0] || 0
      : fields['A La Carte Price'] || 0;
  } else if (fields['A La Carte Rate'] !== undefined) {
    alaCarteRate = fields['A La Carte Rate'] || 0;
  }

  return {
    id: record.id,
    service: fields['Service'] || '',
    description: fields['Description'],
    handldRate,
    alaCarteRate,
    chosenFrequency: isNaN(frequency!) ? undefined : frequency,
    unit: fields['Unit'],
    quoteId: fields['Quote ID (from Request)'] || '',
    linkToQuote: fields['Link to Quote Request']
  };
}

