// LineItem Mappers
// ============================================

/**
 * Maps an Airtable line item record to our domain LineItem model
 */
export function mapAirtableToLineItem(record: AirtableLineItemRecord): LineItem {
  const fields = record.fields;

  // Convert string frequency to number (e.g., "5" -> 5)
  const frequency = fields['Chosen Frequency'] ? parseInt(fields['Chosen Frequency'], 10) : undefined;

  return {
    id: record.id,
    service: fields['Service'] || '',
    description: fields['Description'],
    handldRate: fields['Handld Rate'] || 0,
    alaCarteRate: fields['A La Carte Rate'] || 0,
    chosenFrequency: isNaN(frequency!) ? undefined : frequency,
    unit: fields['Unit'],
    quoteId: fields['Quote ID (from Request)'] || '',
    linkToQuote: fields['Link to Quote Request']
  };
}

/**
 * Maps our domain LineItem model back to Airtable fields for updates
 * Only includes fields that are defined (partial update)
 */
export function mapLineItemToAirtable(lineItem: Partial<LineItem>): Partial<AirtableLineItemFields> {
  const fields: Partial<AirtableLineItemFields> = {};

  if (lineItem.service !== undefined) fields['Service'] = lineItem.service;
  if (lineItem.description !== undefined) fields['Description'] = lineItem.description;
  if (lineItem.handldRate !== undefined) fields['Handld Rate'] = lineItem.handldRate;
  if (lineItem.alaCarteRate !== undefined) fields['A La Carte Rate'] = lineItem.alaCarteRate;

  // Convert number frequency back to string for Airtable single-select field
  if (lineItem.chosenFrequency !== undefined) {
    fields['Chosen Frequency'] = lineItem.chosenFrequency ? String(lineItem.chosenFrequency) : undefined;
  }

  if (lineItem.unit !== undefined) fields['Unit'] = lineItem.unit;

  return fields;
}

/**
 * Maps multiple Airtable line item records to our domain models
 */
export function mapAirtableToLineItems(records: AirtableLineItemRecord[]): LineItem[] {
  return records.map(mapAirtableToLineItem);
}

/**
 * Prepares line item updates for Airtable batch update
 */
export function prepareLineItemUpdates(updates: Array<{ id: string; chosenFrequency?: number }>) {
  return updates.map(update => ({
    id: update.id,
    fields: mapLineItemToAirtable({ chosenFrequency: update.chosenFrequency })
  }));
}

