 */
export function mapAirtableToLineItem(record: AirtableLineItemRecord): LineItem {
  const fields = record.fields;

  // Convert string frequency to number (e.g., "5" -> 5)
  const frequency = fields['Chosen Frequency'] ? parseInt(fields['Chosen Frequency'], 10) : undefined;

  // Handle pricing fields - can be arrays or single values, and have different field names
  let handldRate = 0;
  let alaCarteRate = 0;

  // Try "Handld Price" first, then "Handld Rate"
  if (fields['Handld Price'] !== undefined) {
    handldRate = Array.isArray(fields['Handld Price']) 
      ? fields['Handld Price'][0] || 0
      : fields['Handld Price'] || 0;
  } else if (fields['Handld Rate'] !== undefined) {
    handldRate = fields['Handld Rate'] || 0;
  }

