  if (fields['A La Carte Price'] !== undefined) {
    alaCarteRate = Array.isArray(fields['A La Carte Price'])
      ? fields['A La Carte Price'][0] || 0
      : fields['A La Carte Price'] || 0;
  } else if (fields['A La Carte Rate'] !== undefined) {
    alaCarteRate = fields['A La Carte Rate'] || 0;
  }

  return {
    id: record.id,
    service: fields['Service'] || '',
    description: fields['Description'],
    handldRate,
    alaCarteRate,
    chosenFrequency: isNaN(frequency!) ? undefined : frequency,
    unit: fields['Unit'],
    quoteId: fields['Quote ID (from Request)'] || '',
    linkToQuote: fields['Link to Quote Request']
  };
}

